{
  "title": "Day in Kyoto, pocket-sized",
  "summary": "A slower loop through gold, cedar and lantern light, with stops kept close and bellies kept happy.",
  "stops": [
    {
      "poi_id": "p2",
      "kind": "activity",
      "must_do_id": "m2",
      "note": "KEEP. Shoes off, phone down, eyes up. The gold pavilion earns the early start."
    },
    {
      "poi_id": "p12",
      "kind": "activity",
      "must_do_id": null,
      "note": "A short ride from Kinkaku-ji, and a hall of a thousand faces. Worth one quiet message home."
    },
    {
      "poi_id": "p16",
      "kind": "meal",
      "must_do_id": null,
      "note": "Lunch inside Tenryu-ji's grounds. A kaiseki (multi-course Kyoto meal) that suits the vegetarians, and the budget gets a gentle nod."
    },
    {
      "poi_id": "p6",
      "kind": "activity",
      "must_do_id": null,
      "note": "Right next to lunch. Garden first, then the path back toward town. No long ride needed."
    },
    {
      "poi_id": "p7",
      "kind": "activity",
      "must_do_id": null,
      "note": "Evening in Gion, close to the ryokan (traditional Japanese inn) side of town. Lanterns do the heavy lifting."
    },
    {
      "poi_id": "p20",
      "kind": "meal",
      "must_do_id": null,
      "note": "Dinner at the old soba house. Vegetarian options, warm broth, and a short stroll from Hanamikoji."
    },
    {
      "poi_id": "p13",
      "kind": "activity",
      "must_do_id": null,
      "note": "A nightcap of an alley, close to dinner. The deer will cope without you. The lanterns won't wait."
    }
  ]
}
